    function renderCategoryDistribution(){const categories=categoryFacets.slice(0,5),maximum=categories[0]&&categories[0].count||1;$('#aiCompletedCount').textContent=Number($('#knowledgeEnriched').textContent||0);$('#aiFallbackCount').textContent=dashboard&&Number.isFinite(Number(dashboard.fallback))?dashboard.fallback:0;$('#aiCategoryCount').textContent=categoryFacetTotal||categoryFacets.length;$('#aiCategoryBars').innerHTML=categories.length?categories.map(item=>'<div class="category-row"><span>'+escapeHtml(contentFormatLabel(item.name))+'</span><div class="category-track"><div class="category-fill" style="width:'+Math.max(8,Math.round(item.count/maximum*100))+'%"></div></div><strong>'+item.count+'</strong></div>').join(''):'<div class="ai-empty">尚无分类数据</div>'}
