    async function loadLibrary(reset=false){if(libraryLoading){await libraryLoading;if(!reset)return}if(reset){libraryPage=1;libraryCursors=[null]}const category=libraryCategory,domain=libraryDomain,page=libraryPage,params=new URLSearchParams({limit:'12',organized:'1',active:'1'}),cursor=libraryCursors[libraryPage-1];if(cursor)params.set('before',cursor);if(category)params.set('format',category);if(domain)params.set('domain',domain);$('#libraryListMeta').textContent='正在整理书架…';libraryLoading=(async()=>{const [result,facets]=await Promise.all([api('/api/messages?'+params.toString()),libraryFacets&&!reset?Promise.resolve(libraryFacets):api('/api/knowledge/facets?organized=1&limit=60')]);if(category!==libraryCategory||domain!==libraryDomain||page!==libraryPage)return;libraryFacets=facets;libraryMessages=result.messages||[];libraryTotal=Number(result.pagination&&result.pagination.total||libraryMessages.length);libraryHasMore=Boolean(result.pagination&&result.pagination.hasMore);libraryNextBefore=result.pagination&&result.pagination.nextBefore||null;renderLibrary()})().finally(()=>{libraryLoading=null});await libraryLoading}
