    async function openMindMap(messageId){let data;if(messageId){if(!currentResourceDiagram)await generateResourceDiagram(false);data=currentResourceDiagram;if(!data)return}else data=await api('/api/knowledge/map');$('#mindMapTitle').textContent=messageId&&currentMessage?currentMessage.title+' · '+(data.diagramLabel||'智能图解'):'知识库 · '+(data.diagramLabel||'知识关系图');renderMindMap(data);$('#mindMapDialog').showModal();}
