    const renderResourceSidebarContent=renderResourceSidebar;
    renderResourceSidebar=function(message){renderResourceHeader(message);return renderResourceSidebarContent(message)};
    const openMessageWithoutRoute=openMessage;
    openMessage=async function(id){clearResourceStatusPoll();const changing=!currentMessage||currentMessage.id!==id,target='#reader/'+encodeURIComponent(id);if(location.hash!==target)history.pushState({knowledgeRelayResource:true},'',target);go('reader',false);if(changing){currentMessage=null;$('#dialogTitle').textContent='正在打开内容…';$('#dialogMeta').innerHTML='';$('#messageReprocess').disabled=true;$('#messageReprocess').textContent='正在加载…';$('#resourceReader').innerHTML='<div class="resource-reader-empty">正在准备阅读页面…</div>'}await openMessageWithoutRoute(id);if(currentMessage&&currentMessage.id===id)scheduleResourceStatusPoll(currentMessage);updateReadingProgress()};
    $('#messageArchive').addEventListener('click',async()=>{if(!currentMessage)return;const archived=currentMessage.libraryState==='archived';try{await updateCurrentResource({state:archived?'inbox':'archived',read:true});notice(archived?'已恢复到收件台。':'已归档；内容仍可在“已归档”中查看和恢复。')}catch(error){notice(error.message,true)}});
