    $('#resourceReader').addEventListener('error',event=>{const image=event.target;if(!(image instanceof HTMLImageElement))return;const figure=image.closest('.resource-figure');if(figure)figure.innerHTML='<span class="markdown-image-ref"><span>这张图片暂时无法显示。</span><button class="secondary small" type="button" data-image-retry>重试</button></span>'},{capture:true});
    $('#resourceReader').addEventListener('click',event=>{const retry=event.target.closest('[data-image-retry]');if(retry&&activeResourceDocument)selectResourceDocument(activeResourceDocument)});
    $('#resourceMapStage').addEventListener('click',event=>{if(event.target.closest('[data-map-generate]')||event.target.closest('[data-map-retry]'))generateResourceDiagram(false).catch(()=>{})});
    $('#messageBack').addEventListener('click',()=>{setResourceMobilePanel('reader');if(history.state&&history.state.knowledgeRelayResource)history.back();else{clearResourceStatusPoll();resourceRequestSerial+=1;resourceFetchController?.abort();resourceDocumentController?.abort();currentAttachmentByHash=new Map();currentMessage=null;$('#readingProgress').classList.add('hidden');history.replaceState(null,'','#messages');go('messages',false)}});
    $('#messageReprocess').addEventListener('click',async()=>{if(!currentMessage)return;const id=currentMessage.id,button=$('#messageReprocess');button.disabled=true;button.textContent='正在提交…';try{await api('/api/messages/'+encodeURIComponent(id)+'/reprocess',{method:'POST'});notice('已提交重新整理；当前页面会保留，并在完成后自动载入新版。');if(currentMessage&&currentMessage.id===id){const latest=await api('/api/messages/'+encodeURIComponent(id));currentMessage=latest;renderResourceHeader(latest);renderResourceSidebarContent(latest);scheduleResourceStatusPoll(latest)}await loadMessages(true)}catch(error){notice(error.message,true);if(currentMessage&&currentMessage.id===id)renderResourceHeader(currentMessage)}});
    $('#messageDelete').addEventListener('click',async()=>{if(!currentMessage)return;const id=currentMessage.id,title=currentMessage.title;if(!confirm('永久删除“'+title+'”？\\n\\n原始消息、AI 整理内容、智能图解和所有关联附件都会一起删除，且无法恢复。'))return;const button=$('#messageDelete');button.disabled=true;button.textContent='正在删除…';try{await api('/api/messages/'+encodeURIComponent(id),{method:'DELETE'});clearResourceStatusPoll();currentMessage=null;currentResourceDiagram=null;resourceRequestSerial+=1;history.replaceState(null,'','#messages');go('messages',false);libraryFacets=null;await Promise.all([loadMessages(true),loadFacets()]);notice('内容及其关联附件已永久删除。')}catch(error){notice(error.message,true)}finally{button.disabled=false;button.textContent='永久删除'}});
