    function formatBytes(value){const n=Number(value)||0;if(n<1024)return n+' B';if(n<1048576)return(n/1024).toFixed(1)+' KB';return(n/1048576).toFixed(1)+' MB';}
    async function openPreview(id,name,mime,size=0){const url='/api/attachments/'+encodeURIComponent(id),body=$('#previewBody'),textual=mime.startsWith('text/')||/\\.(?:md|markdown|txt|json|ya?ml|csv|log)$/i.test(name),tooLarge=textual&&size>3*1024*1024||mime.startsWith('image/')&&size>25*1024*1024||mime==='application/pdf'&&size>50*1024*1024;$('#previewTitle').textContent=name;if(tooLarge){body.innerHTML='<div class="resource-reader-empty"><div><strong>这个文件较大，已停止自动预览以保持页面流畅。</strong><br><a class="secondary small" href="'+url+'?download=1">下载文件</a></div></div>';$('#previewDialog').showModal();return}body.innerHTML=textual?'<div class="query-empty">正在读取文本附件…</div>':mime.startsWith('image/')?'<img class="preview-image" src="'+url+'" alt="'+escapeHtml(name)+'" loading="lazy" decoding="async" />':mime.startsWith('audio/')?'<audio controls style="width:100%;margin-top:18px" src="'+url+'"></audio>':mime.startsWith('video/')?'<video controls class="preview-frame" src="'+url+'"></video>':'<iframe class="preview-frame" sandbox src="'+url+'"></iframe>';$('#previewDialog').showModal();if(!textual)return;try{const response=await fetch(url,{headers:{Accept:'text/plain'}});if(!response.ok)throw new Error('HTTP '+response.status);let content=await response.text();if(content.length>3*1024*1024)content=content.slice(0,3*1024*1024)+'\\n\\n> 内容较长，网页仅展示前 3 MB。';const reader=document.createElement('article');reader.className='resource-reader preview-text';reader.innerHTML=renderMarkdown(content);body.replaceChildren(reader);}catch(error){body.innerHTML='<div class="notice error">文本附件预览失败：'+escapeHtml(error.message)+'</div>';}}
    function renderMessages(messages){const empty=resourceView==='all'?'<div class="card empty"><strong>收件台还没有内容</strong><span>连接微信，或创建 API 收件令牌，把第一条链接、文字或附件送进知流。</span><div class="empty-actions"><button class="primary small" type="button" data-empty-go="wechat">连接微信</button><button class="secondary small" type="button" data-empty-go="api">配置 API 收件</button></div></div>':'<div class="card empty"><strong>当前视图还没有内容</strong><span>切换到“当前内容”继续浏览。</span></div>';$('#messagesList').innerHTML=messages.length?messages.map(messageHtml).join(''):empty;const totalPages=Math.max(1,Math.ceil(messageTotal/10));$('#messagePageLabel').textContent='第 '+messagePage+' / '+totalPages+' 页 · 共 '+messageTotal+' 条';$('#previousMessages').disabled=messagePage<=1;$('#nextMessages').disabled=!messageHasMore;$$('[data-empty-go]').forEach(button=>button.addEventListener('click',()=>go(button.dataset.emptyGo)));bindMessages();}
    $('#refreshMessages').addEventListener('click',()=>loadMessages(false));
    async function goMessagePage(direction){if(messageRefresh)await messageRefresh;const previous=messagePage;if(direction>0){if(!messageHasMore||!nextMessageBefore)return;messageCursors[messagePage]=nextMessageBefore;messagePage+=1;}else if(messagePage>1){messagePage-=1;}else return;try{await loadMessages(true);window.scrollTo({top:Math.max(0,$('#messagesList').offsetTop-100),behavior:'smooth'});}catch(error){messagePage=previous;renderMessages(loadedMessages);notice('分页加载失败：'+error.message,true);}}
