    function syncInboxQueryScope(){let scope=$('#queryScope');if(!scope){scope=document.createElement('div');scope.id='queryScope';scope.className='query-scope';scope.setAttribute('aria-label','检索范围');scope.innerHTML='<button type="button" data-query-scope="all">全部内容</button><button type="button" data-query-scope="inbox">待整理收件</button><button type="button" data-query-scope="knowledge">已整理知识</button>';$('#inboxQueryForm').after(scope)}$$('[data-query-scope]').forEach(button=>{const active=button.dataset.queryScope===activeInboxScope;button.classList.toggle('active',active);button.setAttribute('aria-pressed',String(active))})}
    function openInboxQuery(filters={},question='',scope='all'){activeInboxFilters=filters;activeInboxScope=scope;syncInboxQueryScope();$('#inboxQueryInput').value=question;$('#inboxQueryMode').textContent='语义检索';$('#inboxQueryMode').className='pill';$('#inboxQueryAnswer').classList.add('hidden');$('#inboxQueryResults').innerHTML='';if(!$('#inboxQueryDialog').open)$('#inboxQueryDialog').showModal();setTimeout(()=>$('#inboxQueryInput').focus(),0);if(Object.keys(filters).length)runInboxQuery('',filters);}
    async function runInboxQuery(question,filters=activeInboxFilters){const button=$('#submitInboxQuery'),mode=$('#inboxQueryMode'),structured=!question&&Object.keys(filters).length>0,scopedFilters={...filters,scope:activeInboxScope};button.disabled=true;button.textContent='检索中…';mode.textContent=structured?'正在筛选':'AI 正在理解';mode.className='pill warn';$('#inboxQueryResults').innerHTML='<div class="query-empty">'+(structured?'正在匹配该分类下的收件内容…':'Nanobot 正在理解检索需求，并生成本地匹配计划…')+'</div>';try{const result=await api('/api/inbox/query',{method:'POST',body:JSON.stringify({question,filters:scopedFilters})});mode.textContent=result.mode==='nanobot_planned_search'?'Nanobot 已理解':'本地检索结果';mode.className='pill '+(result.mode==='nanobot_planned_search'?'ok':'');$('#inboxQueryAnswer').textContent=result.answer;$('#inboxQueryAnswer').classList.remove('hidden');$('#inboxQueryResults').innerHTML=result.matches.length?result.matches.map(item=>'<article class="query-result" data-query-message="'+escapeHtml(item.id)+'"><strong>'+escapeHtml(item.title)+'</strong><span>'+escapeHtml(item.excerpt||'（仅附件）')+'</span><span class="query-result-meta"><i>'+escapeHtml(categoryLabel(item.category))+'</i>'+[...(item.domains||[]),...(item.knowledgePoints||[]),...(item.tools||[])].slice(0,4).map(value=>'<i>'+escapeHtml(value)+'</i>').join('')+'</span></article>').join(''):'<div class="query-empty">'+(structured?'该分类暂无可显示的收件内容。':'没有匹配结果，换一个更具体的说法试试。')+'</div>';$$('[data-query-message]').forEach(item=>item.addEventListener('click',()=>openMessage(item.dataset.queryMessage)));}catch(error){mode.textContent='检索失败';mode.className='pill warn';$('#inboxQueryResults').innerHTML='';$('#inboxQueryAnswer').textContent=error.message;$('#inboxQueryAnswer').classList.remove('hidden');}finally{button.disabled=false;button.textContent='开始检索';}}
