    $('#connectWechat').addEventListener('click',async()=>{try{const result=await api('/api/ilink/login/start',{method:'POST'});loginSession=result.sessionId;$('#qr').src='/api/ilink/login/'+loginSession+'/qr.svg?x='+Date.now();$('#qrStatus').textContent='请用微信扫码并在手机上确认。';$('#pairWrap').classList.add('hidden');$('#qrDialog').showModal();pollLogin();}catch(error){notice(error.message,true)}});
    async function pollLogin(code){if(polling||!loginSession)return;polling=true;try{const result=await api('/api/ilink/login/'+loginSession+(code?'/verify':'/status'),code?{method:'POST',body:JSON.stringify({code})}:undefined);$('#qrStatus').textContent=result.message;$('#pairWrap').classList.toggle('hidden',result.status!=='need_verifycode');if(result.connected){$('#qrDialog').close();loginSession=null;await refreshAll();notice('微信连接成功，消息接收已经启动。');return;}if(result.status==='need_verifycode')return;if(['expired','error','verify_code_blocked','already_connected'].includes(result.status)){loginSession=null;return;}setTimeout(()=>pollLogin(),1000);}catch(error){$('#qrStatus').textContent=error.message;loginSession=null;}finally{polling=false}}
