    function renderPluginRelease(release){pluginReleaseState=release;const available=release&&release.available;$('#pluginReleaseTitle').textContent=available?'知流同步 · v'+release.version:'尚未发布插件';const details=[];if(available){details.push(formatBytes(release.size));details.push(release.source==='uploaded'?'后台发布':'随系统提供');if(release.publishedAt)details.push(new Date(release.publishedAt).toLocaleString());if(release.sha256)details.push('SHA-256 '+release.sha256.slice(0,12)+'…');}$('#pluginReleaseMeta').textContent=available?details.join(' · '):'上传第一个 ZIP 安装包后即可提供下载';$('#pluginReleaseMeta').title=available&&release.sha256?'完整校验值：'+release.sha256:'';$('#pluginDownload').classList.toggle('hidden',!available);if(available)$('#pluginDownload').href=release.downloadUrl;}
