    function renderProviderFields(provider){if(!provider)return;const oauth=provider.auth==='oauth',local=provider.auth==='local';$('#providerBaseLabel').classList.toggle('hidden',oauth);$('#providerKeyLabel').classList.toggle('hidden',oauth||local);$('#providerOauthPanel').classList.toggle('hidden',!oauth);$('#saveProvider').classList.toggle('hidden',oauth);$('#providerOauth').disabled=oauth&&!providerState.oauthSupported;$('#providerOauthHint').textContent=oauth?(providerState.oauthSupported?'点击后会打开 OpenAI 官方授权页面。':'当前部署环境不支持网页授权，请改用 OpenAI API Key，或在部署终端完成授权。'):'';}
